package org.apache.commons.math3.optimization.univariate;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math3.analysis.UnivariateFunction;
import org.apache.commons.math3.exception.NotStrictlyPositiveException;
import org.apache.commons.math3.exception.NumberIsTooSmallException;
import org.apache.commons.math3.optimization.ConvergenceChecker;
import org.apache.commons.math3.optimization.GoalType;
import org.apache.commons.math3.util.FastMath;
import org.apache.commons.math3.util.Precision;
import org.junit.*;
import org.junit.Test;
import org.mockito.ArgumentMatchers;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Unit tests for BrentOptimizer.doOptimize().
 * Note: Since doOptimize is protected, we use a subclass to expose it for testing.
 */
public class BrentOptimizer_doOptimize_TriageGen0Test {

    private static final double EPSILON = 1e-6;

    /**
     * Test subclass to expose the protected doOptimize method.
     */
    private static class TestableBrentOptimizer extends BrentOptimizer {
        private final UnivariateFunction function;

        public TestableBrentOptimizer(double rel, double abs, UnivariateFunction function) {
            super(rel, abs);
            this.function = function;
        }

        // Overriding computeObjectiveValue to use the provided function
        @Override
        protected double computeObjectiveValue(double x) {
            return function.value(x);
        }

        // Exposing the protected method
        public UnivariatePointValuePair testDoOptimize() {
            return super.doOptimize();
        }

        // Helper to set min/max/start if needed, but constructor usually handles it via optimizer setup.
        // However, BrentOptimizer uses getMin/getMax/getStartValue from the internal state.
        // Since we cannot easily set those via public API without a SearchProblem, 
        // we simulate the behavior by providing a function and using the standard constructor.
    }

    /**
     * Wrapper to provide the necessary setup for BrentOptimizer via a SearchProblem.
     * BrentOptimizer is usually used with an Optimizer class that takes a UnivariateFunction.
     */
    private UnivariatePointValuePair runOptimization(UnivariateFunction function, double min, double max, double start, boolean minimize, double rel, double abs, ConvergenceChecker<UnivariatePointValuePair> checker) {
        // Because BrentOptimizer is an abstract class/part of a hierarchy, 
        // we implement a concrete version that allows us to control the bounds.
        BrentOptimizer optimizer = new BrentOptimizer(rel, abs) {
            @Override
            protected double computeObjectiveValue(double x) {
                return function.value(x);
            }

            @Override
            protected double getMin() { return min; }
            @Override
            protected double getMax() { return max; }
            @Override
            protected double getStartValue() { return start; }
            @Override
            protected GoalType getGoalType() { return minimize ? GoalType.MINIMIZE : GoalType.MAXIMIZE; }
            @Override
            protected ConvergenceChecker<UnivariatePointValuePair> getConvergenceChecker() { return checker; }
            @Override
            protected UnivariatePointValuePair doOptimize() { return super.doOptimize(); }
        };

        // We need to trigger the logic. Since we can't call doOptimize directly from outside 
        // easily without the wrapper above, let's use a specialized Testable class.
        return null; // Placeholder
    }

    // Refined Testable Class to handle all protected methods
    private static class FullTestableBrentOptimizer extends BrentOptimizer {
        private final UnivariateFunction function;
        private final GoalType goalType;
        private final double min;
        private final double max;
        private final double start;
        private final ConvergenceChecker<UnivariatePointValuePair> checker;

        public FullTestableBrentOptimizer(double rel, double abs, UnivariateFunction function, GoalType goalType, double min, double max, double start, ConvergenceChecker<UnivariatePointValuePair> checker) {
            super(rel, abs);
            this.function = function;
            this.goalType = goalType;
            this.min = min;
            this.max = max;
            this.start = start;
            this.checker = checker;
        }

        @Override protected double computeObjectiveValue(double x) { return function.value(x); }
        @Override protected GoalType getGoalType() { return goalType; }
        @Override protected double getMin() { return min; }
        @Override protected double getMax() { return max; }
        @Override protected double getStartValue() { return start; }
        @Override protected ConvergenceChecker<UnivariatePointValuePair> getConvergenceChecker() { return checker; }
        public UnivariatePointValuePair doOptimize() { return super.doOptimize(); }
    }

    @Test
    public void testMinimizeParabola() {
        // f(x) = (x-2)^2 + 3. Min at x=2.
        UnivariateFunction f = x -> Math.pow(x - 2, 2) + 3;
        FullTestableBrentOptimizer optimizer = new FullTestableBrentOptimizer(1e-10, 1e-10, f, GoalType.MINIMIZE, 0, 5, 2.5, null);
        UnivariatePointValuePair result = optimizer.doOptimize();
        assertEquals(2.0, result.getPoint(), 1e-5);
        assertEquals(3.0, result.getValue(), 1e-5);
    }

    @Test
    public void testMaximizeParabola() {
        // f(x) = -(x-2)^2 + 3. Max at x=2.
        UnivariateFunction f = x -> -Math.pow(x - 2, 2) + 3;
        FullTestableBrentOptimizer optimizer = new FullTestableBrentOptimizer(1e-10, 1e-10, f, GoalType.MAXIMIZE, 0, 5, 2.5, null);
        UnivariatePointValuePair result = optimizer.doOptimize();
        assertEquals(2.0, result.getPoint(), 1e-5);
        assertEquals(3.0, result.getValue(), 1e-5);
    }

    @Test
    public void testMinimizerWithReversedBounds() {
        // test logic: if (lo < hi) else { a=hi; b=lo; }
        UnivariateFunction f = x -> Math.pow(x - 2, 2);
        FullTestableBrentOptimizer optimizer = new FullTestableBrentOptimizer(1e-10, 1e-10, f, GoalType.MINIMIZE, 5, 0, 2.5, null);
        UnivariatePointValuePair result = optimizer.doOptimize();
        assertEquals(2.0, result.getPoint(), 1e-5);
    }

    @Test
    public void testConvergenceChecker() {
        UnivariateFunction f = x -> Math.pow(x - 2, 2);
        ConvergenceChecker<UnivariatePointValuePair> mockChecker = mock(ConvergenceChecker.class);
        // Force convergence on first iteration
        when(mockChecker.converged(ArgumentMatchers.anyInt(), ArgumentMatchers.any(), ArgumentMatchers.any())).thenReturn(true);

        FullTestableBrentOptimizer optimizer = new FullTestableBrentOptimizer(1e-10, 1e-10, f, GoalType.MINIMIZE, 0, 5, 2.5, mockChecker);
        UnivariatePointValuePair result = optimizer.doOptimize();

        // Result should be the first calculated 'current' value
        // Since we return immediately, the point will be near the start value
        assertTrue(result != null);
    }

    @Test
    public void testGoldenSectionFallback() {
        // Create a function that is not smooth/parabolic to trigger Golden Section
        // f(x) = |x - 2|
        UnivariateFunction f = x -> Math.abs(x - 2);
        // Large relative/absolute thresholds to ensure we don't just hit parabolic interpolation immediately
        FullTestableBrentOptimizer optimizer = new FullTestableBrentOptimizer(1e-5, 1e-5, f, GoalType.MINIMIZE, 0, 5, 4.5, null);
        UnivariatePointValuePair result = optimizer.doOptimize();
        assertEquals(2.0, result.getPoint(), 1e-3);
    }

    @Test
    public void testParabolicInterpolationBoundary() {
        // Test the branch: if (u - a < tol2 || b - u < tol2)
        // We use a very narrow range and a function that forces 'u' near bounds
        UnivariateFunction f = x -> Math.pow(x - 0.00001, 2);
        FullTestableBrentOptimizer optimizer = new FullTestableBrentOptimizer(1e-10, 1e-10, f, GoalType.MINIMIZE, 0, 1, 0.5, null);
        UnivariatePointValuePair result = optimizer.doOptimize();
        assertEquals(0.00001, result.getPoint(), 1e-6);
    }

    @Test
    public void testFuLessThanFwBranch() {
        // Test the update logic: if (fu <= fw || Precision.equals(w, x))
        UnivariateFunction f = x -> Math.pow(x - 2, 2);
        // Start at a point where the next step 'u' is significantly better than 'w'
        FullTestableBrentOptimizer optimizer = new FullTestableBrentOptimizer(1e-10, 1e-10, f, GoalType.MINIMIZE, 0, 5, 4, null);
        UnivariatePointValuePair result = optimizer.doOptimize();
        assertEquals(2.0, result.getPoint(), 1e-5);
    }

    @Test
    public void testFuLessThanFvBranch() {
        // Test the update logic: else if (fu <= fv || ...)
        UnivariateFunction f = x -> Math.pow(x - 2, 2);
        // This is harder to isolate without complex function design, 
        // but a standard convex function will traverse these branches.
        FullTestableBrentOptimizer optimizer = new FullTestableBrentOptimizer(1e-10, 1e-10, f, GoalType.MINIMIZE, 0, 5, 3, null);
        UnivariatePointValuePair result = optimizer.doOptimize();
        assertEquals(2.0, result.getPoint(), 1e-5);
    }
}
